import { localPoint } from '@visx/event';
import React, { useEffect, useRef, useState } from 'react';

import { MouseCoordinate, OverlaysProps } from '../../../types/overlays.js';
import { isHoverInChartBounds } from '../functions/overlays.js';

type MouseHandler = (e: React.MouseEvent, newState: OverlaysProps) => void;
type FocusHandler = (e: React.FocusEvent, newState: OverlaysProps) => void;

/**
 * Hook responsible of the overlays basic features. It returns the overlay rect, the computed mouse coordinates, the magnifiers values
 * and the closest datapoint. Magnifier and closest point logic it's handled on the consumer side through handlers parameters.
 * @param chartProps - Chart bounds and margins
 * @param onMouseMove - Handler for mouse move
 * @param onMouseEnter - Handler for mouse enter
 * @param onMouseLeave - Handler for mouse leave
 */
export const useOverlays = (
  onMouseMove?: MouseHandler,
  onMouseEnter?: MouseHandler,
  onMouseLeave?: MouseHandler,
  onFocus?: FocusHandler,
  onBlur?: FocusHandler,
) => {
  const overlayRef = useRef<HTMLDivElement>(null);

  const [chartBounds, setChartBounds] = useState<DOMRect>();
  const [isInChartBounds, setIsInChartBounds] = useState<boolean>(false);
  const [mousePosition, setMousePosition] = useState<MouseCoordinate>();
  const [eventLocalPoint, setEventLocalPoint] = useState<MouseCoordinate>();

  // store chart bounds once for avoid expensive calls
  useEffect(() => {
    setChartBounds(overlayRef.current?.getBoundingClientRect());
  }, [mousePosition?.y]);

  const handleMouseMove = (event: React.MouseEvent) => {
    const { clientX, clientY } = event;

    const { x, y } = chartBounds ?? { x: 0, y: 0 };
    const { x: pointX, y: pointY } = localPoint(event) || { x: 0, y: 0 };

    const isInChartBounds = isHoverInChartBounds(event, chartBounds);
    const mousePosition = { x: clientX - x, y: clientY - y };
    const eventLocalPoint = { x: pointX, y: pointY };
    setIsInChartBounds(isInChartBounds);
    setMousePosition(mousePosition);
    setEventLocalPoint(eventLocalPoint);

    onMouseMove?.(event, { isInChartBounds, mousePosition });
  };

  const handleWheel = () => {
    setIsInChartBounds(false);
    setMousePosition(undefined);
    setEventLocalPoint(undefined);
  };

  const handleMouseOut = (event: React.MouseEvent) => {
    const isInChartBounds = isHoverInChartBounds(event, chartBounds);
    setIsInChartBounds(isInChartBounds);
    // needs to be cleaned for hovering the toolbar
    setMousePosition(undefined);
    setEventLocalPoint(undefined);
    onMouseLeave?.(event, { isInChartBounds, mousePosition: undefined });
  };

  const handleMouseEnter = (event: React.MouseEvent) => {
    const { clientX, clientY } = event;
    const { x, y } = (chartBounds as DOMRect) ?? { x: 0, y: 0 };
    const isInChartBounds = isHoverInChartBounds(event, chartBounds);
    const mousePosition = { x: clientX - x, y: clientY - y };

    setIsInChartBounds(isInChartBounds);
    onMouseEnter?.(event, { isInChartBounds, mousePosition });
  };

  const handleFocus = (event: React.FocusEvent) => {
    setIsInChartBounds(true);
    onFocus?.(event, { isInChartBounds, mousePosition });
  };

  const handleBlur = (event: React.FocusEvent) => {
    const nextFocusElement = event.relatedTarget;

    if (!overlayRef.current?.contains(nextFocusElement)) {
      setIsInChartBounds(false);
      onBlur?.(event, { isInChartBounds, mousePosition });
    }
  };

  return {
    handleMouseOut,
    handleMouseEnter,
    handleMouseMove,
    handleFocus,
    handleBlur,
    handleWheel,
    overlayRef,
    mousePosition,
    eventLocalPoint,
    isInChartBounds,
    chartBounds,
  };
};
